const FLAGS=['intro','arrival','beaumont','rook','agnes','mercer','chase','chaseWon','lock','lockFailed','rescued','watsonSent','ending','late','stationVisit','printVisit','trapVisit','printerLead'];
export function fresh(){return {version:1,caseId:CASE_ID,area:'study',pos:{x:.49,y:.78},turns:0,flags:{},clues:[],deductions:[],journal:[],rolls:[],node:'intro',page:0,ending:null,sound:false,savedAt:null};}
export function time(s){const m=21*60+15+Math.min(s.turns,40)*5;return `${String(Math.floor(m/60)%24).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`;}
export function tick(s,n=1){s.turns=Math.min(40,s.turns+n);if(s.turns>=18)s.flags.late=true;}
export function addClue(s,id){if(!CLUES[id])throw Error('Unbekannter Hinweis');if(!s.clues.includes(id)){s.clues.push(id);s.journal.push({text:`Gesichert: ${CLUES[id].name}`,time:time(s)});return true;}return false;}
export function dice(sides=20){let n;const max=Math.floor(4294967296/sides)*sides,a=new Uint32Array(1);do{crypto.getRandomValues(a);n=a[0];}while(n>=max);return n%sides+1;}
export function roll(skill,dc,value=dice()){if(!SKILLS[skill]||!Number.isInteger(value)||value<1||value>20)throw Error('Ungültige Probe');const bonus=SKILLS[skill].bonus;return {value,bonus,total:value+bonus,dc,success:value+bonus>=dc};}
export function deduce(s,a,b,hypothesis){if(s.ending)throw Error('Der Fall ist abgeschlossen.');if(a===b||![a,b].every(k=>s.clues.includes(k)))return {ok:false,text:'Wähle zwei verschiedene gesicherte Beweise.'};const d=DEDUCTIONS[hypothesis];if(!d)throw Error('Unbekannte Schlussfolgerung');if(d.pair.every(k=>[a,b].includes(k))){if(!s.deductions.includes(hypothesis)){s.deductions.push(hypothesis);s.journal.push({text:d.title,time:time(s)});}return {ok:true,text:d.explain};}return {ok:false,text:'Diese beiden Beweise tragen diese Schlussfolgerung noch nicht. Prüfe, was sie wirklich belegen: Ort, Zeitpunkt oder Motiv. Das Nachdenken kostet keine Spielzeit.'};}
export function canTravel(s,id){if(['study','theatre','dressing','backstage','alley'].includes(id))return !!s.flags.intro;if(id==='station')return s.clues.includes('ticket');if(id==='printer')return s.clues.includes('contract')||s.flags.agnes||s.flags.printerLead;if(id==='trap')return s.deductions.includes('route');return false;}
export function travel(s,id){if(s.ending||!canTravel(s,id))throw Error('Dieser Ort ist noch nicht erschlossen.');if(s.area!==id){tick(s);s.area=id;s.pos={x:.5,y:.8};s.node=null;s.page=0;}return s;}
export function finish(s,suspect){if(s.ending)return s.ending;if(!['rook','beaumont','mercer','none'].includes(suspect))throw Error('Unbekannte Entscheidung');const proof=s.deductions.includes('opportunity')&&s.deductions.includes('motive');
if(suspect==='none')s.ending=s.flags.rescued?'rescue':'unfinished';else if(suspect!=='rook')s.ending='wrong';else if(!proof)s.ending='unsupported';else if(s.flags.late)s.ending=s.flags.rescued?'late':'lateUnrescued';else s.ending=s.flags.rescued?'complete':'proofOnly';s.accused=suspect;s.flags.ending=true;s.node='epilogue';s.page=0;return s.ending;}
export function hydrate(raw){if(!raw||raw.version!==1||raw.caseId!==CASE_ID)throw Error('Das ist kein Spielstand von „Die letzte Vorstellung“.');const s=fresh();s.turns=Math.max(0,Math.min(40,Math.floor(Number(raw.turns)||0)));s.flags=Object.fromEntries(FLAGS.filter(k=>raw.flags?.[k]===true).map(k=>[k,true]));s.clues=[...new Set((Array.isArray(raw.clues)?raw.clues:[]).filter(k=>CLUES[k]))];s.deductions=[...new Set((Array.isArray(raw.deductions)?raw.deductions:[]).filter(k=>DEDUCTIONS[k]&&DEDUCTIONS[k].pair.every(c=>s.clues.includes(c))))];s.area=canTravel(s,raw.area)?raw.area:'study';s.pos={x:Math.max(.15,Math.min(.85,Number(raw.pos?.x)||.5)),y:Math.max(.3,Math.min(.87,Number(raw.pos?.y)||.78))};s.journal=Array.isArray(raw.journal)?raw.journal.slice(-80).filter(x=>typeof x.text==='string').map(x=>({text:x.text.slice(0,700),time:typeof x.time==='string'?x.time.slice(0,5):''})):[];s.rolls=Array.isArray(raw.rolls)?raw.rolls.slice(-20).filter(x=>typeof x==='string'):[];s.node=typeof raw.node==='string'?raw.node.slice(0,50):null;s.page=Math.min(20,Math.max(0,Math.floor(Number(raw.page)||0)));s.sound=false;s.lastSuccess=raw.lastSuccess===true;if(raw.ending&&['complete','late','lateUnrescued','wrong','unsupported','rescue','unfinished','proofOnly'].includes(raw.ending)){s.ending=raw.ending;s.accused=['rook','beaumont','mercer','none'].includes(raw.accused)?raw.accused:'none';s.node='epilogue';}if(s.turns>=18)s.flags.late=true;return s;}
export function continuity(s){return {series:'Holmes & Watson – Die ungeschriebenen Fälle',case:1,ending:s.ending,claraRescued:!!s.flags.rescued,rookIdentified:s.accused==='rook'&&s.deductions.includes('opportunity')&&s.deductions.includes('motive'),policeTrust:s.ending==='complete'?2:s.ending==='wrong'?-2:0,patronCode:'V-17',futureCompanion:'Watson'};}
